    const service = { status: statuses[Math.floor(Math.random() * statuses.length)], note: 'Last seen ' + formatTime(new Date(Date.now() - Math.random() * 86400000)) };
    badge.classList.add(`status-${service.status}`);
    const label = document.createElement('span');
    label.textContent = statusText[service.status] || "Unknown";
    badge.append(dot, label);
    header.append(name, badge);
    const meta = document.createElement("div");
    meta.className = "meta";
    meta.innerHTML = `<span class="dot"></span><span>${service.note}</span><span aria-hidden="true"> </span><span>${formatTime(now)}</span>`;
    card.append(header, meta);
    grid.append(card);
  });
}

renderCards();
